require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/view_helpers.php';require_login();$admin=current_user()['role']==='admin';$sql='SELECT p.project_id,p.name,p.user_id,u.full_name owner FROM projects p JOIN users u ON u.user_id=p.user_id';$args=[];if(!$admin){$sql.=' WHERE p.user_id=?';$args[]=(int)current_user()['user_id'];}$sql.=' ORDER BY p.name';$q=$pdo->prepare($sql);$q->execute($args);$projects=$q->fetchAll();$labels=['No critical or high vulnerabilities','All dependencies use pinned exact versions','Latest manifest fully assessed in the scan','Latest scan is no older than 30 days'];page_header('Compliance Checks');?>
<div class="page-heading"><div><span class="eyebrow">SECURITY BASELINE</span><h1>Compliance Checks</h1><p>One current baseline assessment per project.</p></div></div><div class="alert alert-info">These four checks are an internal SupplyGuard baseline only. They are not a certification, regulatory attestation or substitute for a complete security audit.</div>
<div class="card"><div class="card-header"><strong>Project compliance status</strong><span class="small text-secondary">Four baseline checks</span></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Project</th><?php if($admin):?><th>Owner</th><?php endif;?><th>Latest scan</th><th>Overall status</th><th>Baseline rules</th><th>Review</th></tr></thead><tbody><?php foreach($projects as $p):$c=compliance_for_scan($pdo,(int)$p['project_id']);?><tr><td><strong><?=e($p['name'])?></strong></td><?php if($admin):?><td><?=e($p['owner'])?></td><?php endif;?><td><?=e($c['run']['scanned_at']??'—')?></td><td><?=compliance_badge($c['status'])?></td><td><div class="d-grid gap-1"><?php foreach($labels as $i=>$label):?><span class="small"><i class="bi <?=!empty($c['rules'][$i])?'bi-check-circle-fill text-success':'bi-x-circle-fill text-danger'?> me-1"></i><?=e($label)?></span><?php endforeach;?></div></td><td><?php if($c['run']):?><a class="btn btn-sm btn-outline-primary" href="<?=e(url('scan.php?id='.$c['run']['run_id']))?>">Scan</a> <?=report_action($pdo,(int)$c['run']['run_id'],$admin)?><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$projects):?><tr><td colspan="<?=$admin?6:5?>" class="empty-state">No projects available for assessment.</td></tr><?php endif;?></tbody></table></div></div><?php require APP_ROOT.'/includes/footer.php';?>
